import{_ as e,o,c as d,ak as a}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"SVN → GitLab · 00 编排","description":"编排 SVN→本地 GitLab 迁移全流程（编号 Skills 01–04），保留提交历史；参数化 SVN URL 与目标 Group。 在用户说 SVN 迁 Git、svn-to-git、保留日志迁仓、按步骤迁 SVN 时使用。","frontmatter":{"name":"svn-to-git-00-orchestrate","description":"编排 SVN→本地 GitLab 迁移全流程（编号 Skills 01–04），保留提交历史；参数化 SVN URL 与目标 Group。 在用户说 SVN 迁 Git、svn-to-git、保留日志迁仓、按步骤迁 SVN 时使用。"},"headers":[],"relativePath":"docs/assets/attachments/gitlab-skills/svn-to-git-00-orchestrate/SKILL.md","filePath":"docs/assets/attachments/gitlab-skills/svn-to-git-00-orchestrate/SKILL.md"}'),i={name:"docs/assets/attachments/gitlab-skills/svn-to-git-00-orchestrate/SKILL.md"};function r(l,t,s,c,n,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="svn-→-gitlab-·-00-编排" tabindex="-1">SVN → GitLab · 00 编排 <a class="header-anchor" href="#svn-→-gitlab-·-00-编排" aria-label="Permalink to &quot;SVN → GitLab · 00 编排&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在<strong>保留作者/时间/说明</strong>的前提下，把 SVN 项目迁入内网 GitLab（默认 <code>http://192.168.1.173</code>），并完成试迁验收与切换约定。</p><p>本系列 Skills：<code>.cursor/skills/svn-to-git-*</code>。<br> 人类命令长文：项目根目录 <code>3.SVN到Git迁移方案与操作手册.md</code>。</p><h2 id="已拍板默认策略-改口须用户明确说" tabindex="-1">已拍板默认策略（改口须用户明确说） <a class="header-anchor" href="#已拍板默认策略-改口须用户明确说" aria-label="Permalink to &quot;已拍板默认策略（改口须用户明确说）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>代号</th><th>决策</th></tr></thead><tbody><tr><td>工具</td><td><code>git svn clone</code>（不用 svn export；不用长期 SubGit 双写）</td></tr><tr><td>H1</td><td>全历史</td></tr><tr><td>G1</td><td>方案1：产品顶层 Group + 子组 <code>PC</code>/<code>MC</code>/<code>MX</code>；<strong>先建组再迁仓</strong></td></tr><tr><td>A1</td><td>先 <code>authors.txt</code> 映射，再正式 clone</td></tr><tr><td>C1</td><td>试迁 1 仓 → 批量 → SVN 只读切换</td></tr><tr><td>布局</td><td>标准 trunk/branches/tags 用 <code>-s</code>；无 trunk 则该仓不加 <code>-s</code></td></tr><tr><td>首迁</td><td>不清洗 <code>git-svn-id</code>；验证后再谈 <code>filter-repo</code></td></tr><tr><td>推送</td><td>本机经 <code>git_http_tunnel.bat</code> → <code>http://127.0.0.1:18173/...</code></td></tr></tbody></table><h2 id="换批次-新清单时先做" tabindex="-1">换批次/新清单时先做 <a class="header-anchor" href="#换批次-新清单时先做" aria-label="Permalink to &quot;换批次/新清单时先做&quot;">​</a></h2><ol><li>读取 <a href="./env-template.html">env-template.md</a> 与 <a href="./project-list-template.html">project-list-template.md</a>。</li><li>回显变量与项目表（<strong>不含 SVN/GitLab 密码</strong>）请用户确认。</li><li>从 <strong>01</strong> 开始；已完成步骤可跳过并记录原因。</li></ol><h2 id="执行顺序-强制" tabindex="-1">执行顺序（强制） <a class="header-anchor" href="#执行顺序-强制" aria-label="Permalink to &quot;执行顺序（强制）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>Skill</th><th>产出门槛（未达成不得进下一步）</th></tr></thead><tbody><tr><td>01</td><td><code>svn-to-git-01-inventory</code></td><td>SVN 可达；布局 L1/L2 已判定；作者草稿已导出</td></tr><tr><td>02</td><td><code>svn-to-git-02-convert</code></td><td>本地 <code>git svn</code> 仓存在；<code>git log</code> 可抽样核对</td></tr><tr><td>03</td><td><code>svn-to-git-03-push-gitlab</code></td><td>GitLab Private 空仓已建；<code>--all</code>/<code>--tags</code> 已推；网页可见历史</td></tr><tr><td>04</td><td><code>svn-to-git-04-cutover</code></td><td>切换清单已交付；SVN 只读动作已确认或明确延期</td></tr></tbody></table><h2 id="agent-行为规则" tabindex="-1">Agent 行为规则 <a class="header-anchor" href="#agent-行为规则" aria-label="Permalink to &quot;Agent 行为规则&quot;">​</a></h2><ol><li><strong>一次只跑一个编号 Skill</strong>，除非用户明确「按清单试迁/批量全跑」。</li><li>每步结束输出：<code>完成项</code> / <code>未完成项</code> / <code>下一步 Skill 名</code>。</li><li><strong>未拿到项目清单与 authors 确认前，禁止正式 clone/push。</strong></li><li>禁止把 SVN/GitLab 密码、PAT 写入 skill、手册、仓库。</li><li>不批量改同事机器；不做长期 SVN/Git 双写；不大文件历史重写（另开任务）。</li><li>推送前确认 <code>git_http_tunnel.bat</code> 已开（本环境 <code>git.exe</code> 直连 GitLab HTTP 易 400）。</li></ol><h2 id="全流程验收-04-之后" tabindex="-1">全流程验收（04 之后） <a class="header-anchor" href="#全流程验收-04-之后" aria-label="Permalink to &quot;全流程验收（04 之后）&quot;">​</a></h2><ul><li>[ ] 至少一个试迁仓网页历史与 SVN 抽样一致</li><li>[ ] 目标 Group/保护分支符合现网规范</li><li>[ ] 切换日与 SVN 只读策略已书面约定</li><li>[ ] 其余清单项目已迁或已排期</li></ul><h2 id="触发话术示例" tabindex="-1">触发话术示例 <a class="header-anchor" href="#触发话术示例" aria-label="Permalink to &quot;触发话术示例&quot;">​</a></h2><ul><li>「读取 svn-to-git-00，按清单试迁第 1 个项目」</li><li>「执行 svn-to-git-01-inventory，URL=…」</li><li>「authors 已确认，开始 svn-to-git-02」</li></ul>',16)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
